style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/YyKqAao.png") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #fff !important;
    }

    .container-header, .content, .navbar, .section, .game-home-page, .games-page, .game-card-container {
        background-color: rgba(0, 0, 0, 0.6) !important;
        border: none !important;
    }

    button, .btn-primary, .btn-secondary, input, select {
        background-color: #222 !important;
        color: #eee !important;
        border: 1px solid #444 !important;
        border-radius: 8px !important;
    }

    button:hover, .btn-primary:hover {
        background-color: #444 !important;
    }

    .ads-container, .sponsored-games, .promo-banner {
        display: none !important;
    }

    a {
        color: #88ccff !important;
    }

    a:hover {
        color: #ffffff !important;
    }
}
